using FluentAssertions;
using UnitTests.Parser.Census;

namespace ZorkOne.Tests.Parser;

/// <summary>
///     Every interaction in Zork I that changes the game, from <c>interactions.zorkone.json</c>, each
///     checked through the production parser. The file is not written by hand: it is what the game
///     itself answers (see <see cref="InteractionSet" />), regenerated by the explicit test below.
/// </summary>
[TestFixture]
public class InteractionSetTests
{
    private const string FileName = "interactions.zorkone.json";

    private static readonly InteractionCensus Census = new(ZorkOneCensus.Game);

    private static IEnumerable<Interaction> All()
    {
        return InteractionSet.Load(typeof(InteractionSetTests).Assembly, FileName);
    }

    [TestCaseSource(nameof(All))]
    public async Task EveryWording_ThroughTheProductionParser_DoesWhatTheGameDoes(Interaction interaction)
    {
        var problems = await InteractionSet.Check(Census, interaction,
            (verb, noun) => InteractionSet.ProductionParser(ZorkOneCensus.Game, verb, noun));

        problems.Should().BeEquivalentTo(Array.Empty<string>());
    }

    [Test]
    [Explicit("Rewrites interactions.zorkone.json from what the game answers today. Long on one core; to use " +
              "several, set INTERACTION_SET_PART to 1/4, 2/4 ... in as many shells, then run the merge below")]
    public async Task RegenerateTheInteractionSet()
    {
        TestContext.Out.WriteLine(
            await InteractionSet.Regenerate(Census, "ZorkOne.Tests", FileName, TestContext.Progress.WriteLine));
    }

    [Test]
    [Explicit("Writes interactions.zorkone.json from the parts RegenerateTheInteractionSet left behind")]
    public void MergeTheInteractionSetParts()
    {
        TestContext.Out.WriteLine(InteractionSet.MergeParts("ZorkOne.Tests", FileName));
    }
}
